   // Same canonical code as huffman_enc: 256 8-bit symbols, frequency model
   // freq[s] = round(1e6 * 0.98^s), max code length 13 bits. Puff-style
   // canonical decode needs only:
   //   cnt_rom(L)  : number of codewords of length L (L = 1..15)
   //   dsym_rom(i) : the i-th symbol in canonical order (sorted by code length,
   //                 then by symbol value)
   //##########################################################################
   function [8:0] cnt_rom;
      input [3:0] L;
      begin
         case (L)
           4'd1: cnt_rom = 9'd0;
           4'd2: cnt_rom = 9'd0;
           4'd3: cnt_rom = 9'd0;
           4'd4: cnt_rom = 9'd0;
           4'd5: cnt_rom = 9'd0;
           4'd6: cnt_rom = 9'd30;
           4'd7: cnt_rom = 9'd34;
           4'd8: cnt_rom = 9'd35;
           4'd9: cnt_rom = 9'd35;
           4'd10: cnt_rom = 9'd34;
           4'd11: cnt_rom = 9'd34;
           4'd12: cnt_rom = 9'd34;
           4'd13: cnt_rom = 9'd20;
           4'd14: cnt_rom = 9'd0;
           4'd15: cnt_rom = 9'd0;
           default: cnt_rom = 9'd0;
         endcase
      end
   endfunction

